import read_line, ReadStream, stdin from "@std/io/io.ms"

fn limit() Int:
    return 1 / "".byte_length()

fn probe(input: ReadStream) Bool:
    if let line = read_line(input, limit()):
        return line.is_some()

    return false

export fn main() Int:
    if probe(stdin()): return 1

    return 0
